// Standard weight/volume unit conversions (approximated at water density for
// volume units — the same simplification virtually every food-tracking app
// uses). A food's `units` field lists which of these it can also be logged
// in; `customUnit` adds one food-specific "piece" unit (1 egg, 1 slice, 1
// banana...). Grams is always available as the universal fallback.
export const UNIT_DEFS = {
  g: { id: "g", label: "g", grams: 1 },
  ml: { id: "ml", label: "ml", grams: 1 },
  tbsp: { id: "tbsp", label: "tbsp", grams: 15 },
  tsp: { id: "tsp", label: "tsp", grams: 5 },
  cup: { id: "cup", label: "cup", pluralLabel: "cups", grams: 240 },
  oz: { id: "oz", label: "oz", grams: 28 },
};

// The full list of loggable units for a food, in display order: grams
// first (universal default), then its own "piece" unit if it has one,
// then any other declared units (tbsp, cup, etc).
export function unitsFor(food) {
  const list = [UNIT_DEFS.g];
  if (food.customUnit) list.push({ id: "piece", ...food.customUnit });
  (food.units || []).forEach((id) => {
    if (UNIT_DEFS[id] && id !== "g") list.push(UNIT_DEFS[id]);
  });
  return list;
}

// Micronutrients a food can optionally carry (per-100g/ml, same convention
// as cals/protein/carbs/fat) — grams-scale fields first, then mg-scale.
// Only ever populated from a real source (Open Food Facts' own nutriments,
// or a coach/client typing in a label's numbers) — never invented, so most
// of the static built-in database simply omits them rather than guessing.
export const MICRO_FIELDS_G = ["satFat", "transFat", "fiber", "sugar"];
export const MICRO_FIELDS_MG = ["sodium", "potassium", "calcium", "iron", "cholesterol", "vitaminC"];
export const MICRO_FIELDS = [...MICRO_FIELDS_G, ...MICRO_FIELDS_MG];

// Scales a per-100g/ml database entry to a chosen gram/ml quantity, returning
// a "resolved" food object with absolute macros — the shape the rest of the
// app already expects (id, name, cals, protein, carbs, fat). Any micronutrient
// fields present on the source food are scaled the same way; fields the food
// doesn't carry are simply left off the result rather than defaulting to 0,
// so "no data" stays distinguishable from "genuinely zero" downstream.
export function scaleFood(food, grams) {
  const g = Math.max(0, Number(grams) || 0);
  const factor = g / (food.per || 100);
  const round1 = (n) => Math.round(n * factor * 10) / 10;
  const resolved = {
    id: food.id,
    baseFoodId: food.id,
    name: `${food.name} (${g}g)`,
    grams: g,
    cals: Math.round(food.cals * factor),
    protein: round1(food.protein),
    carbs: round1(food.carbs),
    fat: round1(food.fat),
  };
  MICRO_FIELDS.forEach((key) => {
    if (food[key] != null) resolved[key] = round1(food[key]);
  });
  return resolved;
}

// Same as scaleFood, but the quantity is expressed in one of a food's
// loggable units (tbsp, cup, "1 egg", etc.) instead of raw grams — the
// unit is converted to grams under the hood, then the name/label reflects
// whatever unit the client actually picked.
export function scaleFoodByUnit(food, unitId, qty) {
  const units = unitsFor(food);
  const unit = units.find((u) => u.id === unitId) || UNIT_DEFS.g;
  const q = Math.max(0, Number(qty) || 0);
  const grams = q * unit.grams;
  const resolved = scaleFood(food, grams);
  const label =
    unit.id === "g" || unit.id === "ml"
      ? `${q}${unit.label}`
      : `${q} ${q === 1 ? unit.label : unit.pluralLabel || `${unit.label}s`}`;
  resolved.name = `${food.name} (${label})`;
  resolved.unitId = unit.id;
  resolved.unitQty = q;
  return resolved;
}
